const items = Array.isArray($input.first().json) ? $input.first().json : [];
console.log(`[Quality] ${items.length} pending items to score`);
if (!items.length) return [];

// Quality scoring function
function qualityScore(item) {
  let score = 0;
  const title = (item.title_ar || '').trim();

  // Title quality (0-25 pts)
  if (title.length >= 5)  score += 10;
  if (title.length >= 15) score += 5;
  if (title.length <= 150) score += 5;
  if (!/http|www|\.com/.test(title)) score += 5; // no URLs in title

  // Metadata completeness (0-30 pts)
  if (item.poster_url)       score += 10;
  if (item.description)      score += 8;
  if (item.year && item.year > 1980 && item.year <= new Date().getFullYear() + 1) score += 5;
  if (item.duration_sec && item.duration_sec > 600) score += 7; // > 10 min

  // Origin/language detection (0-20 pts)
  if (item.origin && item.origin !== 'other')       score += 10;
  if (item.language && item.language !== 'unknown') score += 10;

  // Content validity (0-25 pts)
  if (item.yt_id && item.yt_id.length === 11)   score += 10;
  if (item.embeddable !== false)                 score += 10;
  if (item.type === 'film' && item.duration_sec && item.duration_sec >= 3600) score += 5;
  if (item.type === 'series' && item.total_eps >= 1) score += 5;

  // Penalties
  const lc = title.toLowerCase();
  if (/trailer|teaser|promo|preview|إعلان|بروموشن/.test(lc)) score -= 30;
  if (/part\s*[1-9]|جزء/.test(lc)) score -= 5; // might be cut video

  return Math.max(0, Math.min(100, score));
}

return items.map(item => ({
  json: {
    id: item.id,
    title: item.title_ar,
    score: qualityScore(item),
    auto_publish: qualityScore(item) >= 60
  }
}));

// Keep low-score items as pending (needs manual review)
const item = $input.first().json;
console.log(`[Quality] Low score (${item.score}/100): ${item.title} — kept as pending`);
return [{ json: { kept_pending: true, id: item.id, score: item.score } }];

const items = $input.all();
const published = items.filter(i => !i.json.kept_pending).length;
const pending   = items.filter(i => i.json.kept_pending).length;
console.log(`[Quality] DONE: ${published} auto-published, ${pending} kept pending`);
return [{ json: { published, pending, run_at: new Date().toISOString() } }];
